### math
```javascript
/**
 * Calcule la somme de tous les nombres contenus dans un tableau.
 * @param {number[]} tab - Tableau de nombres.
 * @returns {number} La somme des éléments.
 */
function additionner(tab) {
    return tab.reduce((accumulateur, valeurCourante) => accumulateur + valeurCourante, 0);
}
```

### francais
```javascript
/**
 * Met la première lettre d'un mot en majuscule.
 * @param {string} mot - Le mot à modifier.
 * @returns {string} Le mot avec la première lettre en majuscule.
 */
function majuscule(mot) {
    if (!mot || typeof mot !== 'string') return "";
    return mot.charAt(0).toUpperCase() + mot.slice(1);
}
```

### contient
```javascript
/**
 * Vérifie si un tableau contient une valeur donnée.
 * @param {any[]} tab - Le tableau à vérifier.
 * @param {any} val - La valeur recherchée.
 * @returns {boolean} True si la valeur est présente, false sinon.
 */
function contientValeur(tab, val) {
    return tab.includes(val);
}
```

### absolu
```javascript
/**
 * Calcule la valeur absolue d'un nombre.
 * @param {number} n - Le nombre dont on veut la valeur absolue.
 * @returns {number} La valeur absolue de n.
 */
function valeurAbsolue(n) {
    return Math.abs(n);
}
```

