/**
 * Calcule le Plus Grand Commun Diviseur (PGCD) de deux nombres entiers positifs en utilisant l'algorithme d'Euclide.
 * @param {number} a - Le premier nombre (> 0).
 * @param {number} b - Le deuxième nombre (> 0).
 * @returns {number} Le PGCD de a et b.
 */
function pgcd(a, b) {
    // Algorithme d'Euclide : PGCD(a, b) = PGCD(b, a % b)
    if (b === 0) {
        return a;
    }
    return pgcd(b, a % b);
}
