/**
 * Fusionne deux tableaux déjà triés en un seul tableau trié.
 * Utilise une approche par pointeurs (two-pointer technique).
 * @param {number[]} a - Premier tableau trié.
 * @param {number[]} b - Deuxième tableau trié.
 * @returns {number[]} Le nouveau tableau fusionné et trié.
 */
function fusionTriee(a, b) {
    let result = [];
    let i = 0; // Pointeur pour a
    let j = 0; // Pointeur pour b

    // Tant qu'il reste des éléments dans les deux tableaux
    while (i < a.length && j < b.length) {
        if (a[i] <= b[j]) {
            result.push(a[i]);
            i++;
        } else {
            result.push(b[j]);
            j++;
        }
    }

    // Ajouter les éléments restants de 'a'
    while (i < a.length) {
        result.push(a[i]);
        i++;
    }

    // Ajouter les éléments restants de 'b'
    while (j < b.length) {
        result.push(b[j]);
        j++;
    }

    return result;
}
