 * @param {string} b - Deuxième chaîne.
 * @returns {boolean} True si elles sont des anagrammes, false sinon.
 */
function sontAnagrammes(a, b) {
    // 1. Vérification rapide de la longueur
    if (a.length !== b.length) {
        return false;
    }

    // 2. Créer une fonction utilitaire pour trier les caractères d'une chaîne
    const sortString = (s) => s.split('').sort().join('');

    // 3. Comparer les chaînes après tri
    return sortString(a) === sortString(b);
}
