/**
 * Calcule le discriminant (delta) d'une équation quadratique: b^2 - 4ac.
 * @param {number} a Coefficient de x^2.
 * @param {number} b Coefficient de x.
 * @param {number} c Terme constant.
 * @returns {number} Le discriminant delta.
 */
const discriminant = (a, b, c) => {
    return (b * b) - (4 * a * c);
};
```

