```javascript
/**
 * Vérifie si un mot est un palindrome (se lit de la même manière à l'envers).
 * @param {string} mot Le mot à tester.
 * @returns {boolean} True si le mot est un palindrome, false sinon.
 */
const estPalindrome = (mot) => {
    // Nettoyer le mot pour ne garder que les caractères alphabétiques et minuscules
    const cleanMot = mot.toLowerCase().replace(/[^a-z0-9]/g, '');
    const reversMot = cleanMot.split('').reverse().join('');
    return cleanMot === reversMot;
};
```

