 * Formule: (C * 9/5) + 32.
 * @param {number} c Température en degrés Celsius.
 * @returns {number} Température équivalente en degrés Fahrenheit.
 */
const celsiusToFahrenheit = (c) => {
    return (c * 9 / 5) + 32;
};
