/**
 * Calcule la médiane d'un tableau de nombres.
 * Tri nécessaire : le tableau doit être trié pour trouver la médiane.
 * @param {number[]} tab Le tableau de nombres.
 * @returns {number} La valeur médiane.
 */
const mediane = (tab) => {
    if (!tab || tab.length === 0) return 0;

    // 1. Créer une copie et trier le tableau par ordre croissant
    const sortedTab = [...tab].sort((a, b) => a - b);
    const length = sortedTab.length;
    const middleIndex = Math.floor(length / 2);

    if (length % 2 === 1) {
        // Longueur impaire : la médiane est l'élément du milieu
        return sortedTab[middleIndex];
    } else {
        // Longueur paire : la médiane est la moyenne des deux éléments centraux
        const value1 = sortedTab[middleIndex - 1];
        const value2 = sortedTab[middleIndex];
        return (value1 + value2) / 2;
    }
};
```

