```javascript
/**
 * Calcule la moyenne pondérée à partir d'un tableau d'objets {valeur, coeff}.
 * @param {Array<{valeur: number, coeff: number}>} notes - Tableau des notes avec leurs coefficients.
 * @returns {number} La moyenne pondérée, ou 0 si le tableau est vide.
 */
function moyennePonderee(notes) {
    if (!notes || notes.length === 0) {
        return 0;
    }

    let sommeProduits = 0;
    let sommeCoeffs = 0;

    for (const note of notes) {
        sommeProduits += note.valeur * note.coeff;
        sommeCoeffs += note.coeff;
    }

    if (sommeCoeffs === 0) {
        return 0; // Évite la division par zéro si tous les coefficients sont nuls
    }

    return sommeProduits / sommeCoeffs;
}
```

