    const words = phrase.toLowerCase().match(/\b\w+\b/g) || [];
    const compteurs = {};

    for (const word of words) {
        if (compteurs[word]) {
            compteurs[word]++;
        } else {
            compteurs[word] = 1;
        }
    }
    return compteurs;
}
