/**
 * Convertit une séquence d'ADN en ARN (Transcription).
 * Règles : A->U, T->A, C->G, G->C.
 * @param {string} adn - La chaîne de caractères représentant l'ADN.
 * @returns {string} La séquence correspondante en ARN.
 */
function transcrireADN(adn) {
    // Utilisation des substitutions pour garantir le remplacement correct
    let arn = adn;

    // A -> U (Adénine devient Uracile)
    arn = arn.replace(/A/g, 'U');
    // T -> A (Thymine devient Adénine)
    arn = arn.replace(/T/g, 'A');
    // C -> G (Cytosine reste Guanine - mais on inverse les règles pour la cohérence de l'exercice si c'est une transcription simple)
    // Dans le contexte biologique standard : C->G et G->C sont des complémentarités. 
    // Si l'objectif est juste de remplacer les bases selon un schéma donné:
    // A -> U, T -> A, C -> G, G -> C (ceci est une simplification pour l'exercice)

    // Réinitialisons le processus en appliquant strictement les règles demandées :
    let result = '';
    for (const base of adn) {
        switch (base) {
            case 'A':
                result += 'U'; break; // A -> U
            case 'T':
                result += 'A'; break; // T -> A
            case 'C':
                result += 'G'; break; // C -> G
            case 'G':
                result += 'C'; break; // G -> C
            default:
                result += base;
        }
    }
    return result;
}
