/**
 * Convertit un entier non négatif n en sa représentation en chaîne de caractères dans la base donnée (2-16).
 * @param {number} n - L'entier à convertir.
 * @param {number} base - La base cible (entre 2 et 16).
 * @returns {string} La représentation de n en base 'base'.
 */
function convertirBase(n, base) {
    if (n === 0) return "0";

    const digits = "0123456789abcdef";
    let result = "";

    while (n > 0) {
        // Calculer le reste pour obtenir le chiffre en base 'base'
        const remainder = n % base;
        result = digits[remainder] + result;
        // Diviser par la base pour passer au chiffre suivant
        n = Math.floor(n / base);
    }

    return result;
}
