/**
 * Retourne la k-ième plus grand élément distinct d'un tableau (1-indexé).
 * @param {Array<number>} tab - Le tableau d'entrée.
 * @param {number} k - L'indice de rang souhaité (k=1 pour le plus grand).
 * @returns {number} La k-ième valeur la plus grande et distincte.
 */
function kemePlusGrand(tab, k) {
    // 1. Obtenir les valeurs distinctes
    const distinctValues = [...new Set(tab)];

    // 2. Trier ces valeurs par ordre décroissant
    distinctValues.sort((a, b) => b - a);

    // 3. Retourner l'élément à l'index k-1 (car k est 1-indexé)
    if (k > distinctValues.length || k <= 0) {
        throw new Error("K invalide ou dépasse le nombre d'éléments distincts.");
    }

    return distinctValues[k - 1];
}
