/**
 * Calcule x élevé à la puissance n (x^n) en utilisant l'exponentiation rapide (Exponentiation by Squaring).
 * @param {number} x - La base.
 * @param {number} n - L'exposant (doit être >= 0).
 * @returns {number} Le résultat de x^n.
 */
function exponentiationRapide(x, n) {
    if (n === 0) return 1;
    if (n < 0) throw new Error("L'exposant doit être non négatif.");

    let result = 1;
    let base = x;
    let power = n;

    while (power > 0) {
        // Si le bit de poids faible est 1 (n est impair)
        if (power % 2 === 1) {
            result *= base;
        }
        // Élever la base au carré pour l'itération suivante
        base *= base;
        // Décaler les bits vers la droite (diviser par 2, ou faire un shift de 1)
        power = Math.floor(power / 2);
    }

    return result;
}
