/**
 * Trouve la somme maximale d'un sous-tableau contigu en utilisant l'algorithme de Kadane.
 * @param {number[]} tab - Le tableau d'entrée.
 * @returns {number} La somme maximale possible.
 */
function sousTableauMax(tab) {
    if (!tab || tab.length === 0) {
        return 0;
    }

    // maxSoFar : la somme maximale trouvée jusqu'à présent dans tout le tableau.
    let maxSoFar = tab[0];
    // currentMax : la somme maximale se terminant à l'indice actuel.
    let currentMax = tab[0];

    for (let i = 1; i < tab.length; i++) {
        const element = tab[i];

        // Le maximum courant est soit l'élément lui-même, soit l'élément ajouté au max précédent.
        currentMax = Math.max(element, currentMax + element);

        // Mettre à jour le maximum global si le maximum courant est plus grand.
        maxSoFar = Math.max(maxSoFar, currentMax);
    }

    return maxSoFar;
}
