        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            if (tails[mid] >= target) {
                // Potential candidate found, try for an even smaller index
                resultIndex = mid;
                right = mid - 1;
            } else {
                // tails[mid] < target, must search in the right half
                left = mid + 1;
            }
        }
        return resultIndex;
    };

    for (const num of tab) {
