        let i = binarySearch(num);

        if (i === tails.length) {
            // Case 1: Num is larger than all current tails. Extend the LIS length by 1.
            tails.push(num);
        } else {
            // Case 2: Found a tail element at index 'i' that can be replaced by a smaller number (num).
            // This ensures that for subsequences of length i+1, we maintain the smallest possible tail.
            tails[i] = num;
        }
    }

    // The length of the 'tails' array is the length of the LIS.
    return tails.length;
}

