/**
 * Tri sorts an array of numbers in ascending order without using Array.prototype.sort().
 * Implements Merge Sort for O(N log N) time complexity.
 * @param {number[]} arr The array to sort.
 * @returns {number[]} The sorted array.
 */
function trier_tableau(arr) {
    if (!arr || arr.length < 2) {
        return arr;
    }

    const merge = (left, right) => {
        let result = [];
        let i = 0;
        let j = 0;

        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                result.push(left[i]);
                i++;
            } else {
                result.push(right[j]);
                j++;
            }
        }

        return result.concat(i < left.length ? left.slice(i) : []);
    };

    const mergeSort = (array) => {
        if (array.length <= 1) {
            return array;
        }

        const middle = Math.floor(array.length / 2);
        const left = array.slice(0, middle);
        const right = array.slice(middle);

        const sortedLeft = mergeSort(left);
        const sortedRight = mergeSort(right);

        return merge(sortedLeft, sortedRight);
    };

    return mergeSort(arr);
}
