function medianeDeuxTries(a, b) {
    // Ensure A is the smaller array to minimize search space (O(log(min(m, n))))
    if (a.length > b.length) {
        return medianeDeuxTries(b, a);
    }

    const m = a.length;
    const n = b.length;
    const totalLength = m + n;
    // The target partition size for the left half (k elements)
    const halfLen = Math.floor((totalLength + 1) / 2);

    let low = 0;
    let high = m; // Search space is on array A's partition point

    while (low <= high) {
        // Partition point for A: i elements in the left half of A
        const i = Math.floor((low + high) / 2);
        // Required partition point for B: j elements in the left half of B
        const j = halfLen - i;

        // Define boundary values (handling edge cases where partitions are empty)
        const aLeftMax = (i === 0) ? Number.NEGATIVE_INFINITY : a[i - 1];
        const aRightMin = (i === m) ? Number.POSITIVE_INFINITY : a[i];

        const bLeftMax = (j === 0) ? Number.NEGATIVE_INFINITY : b[j - 1];
        const bRightMin = (j === n) ? Number.POSITIVE_INFINITY : b[j];

