        // 1. Max of left half <= Min of right half for both arrays.
        if (aLeftMax <= bRightMin && bLeftMax <= aRightMin) {
            // Found the perfect split!
            const maxLeft = Math.max(aLeftMax, bLeftMax);

            if (totalLength % 2 === 1) {
                // Odd total length: Median is the largest element in the left half
                return maxLeft;
            } else {
                // Even total length: Median is the average of the two middle elements
                const minRight = Math.min(aRightMin, bRightMin);
                return (maxLeft + minRight) / 2.0;
